operations.before:
- name: Download and load exact hosted-verified image
  if: env.R9_RESUME_CANDIDATE != '1'
  timeout-minutes: 25
  uses: actions/download-artifact@d3f86a106a0bac45b974a628896c90dbdf5c8093
  with:
    name: arthello-v52-verification-${{ env.TRIGGER_VERIFY_RUN_ID }}
    path: ${{ runner.temp }}/arthello-v52-release-${{ github.run_id }}
    github-token: ${{ github.token }}
    run-id: ${{ env.TRIGGER_VERIFY_RUN_ID }}
